<script lang="ts">
  import {language,translate,itemName,roomName} from '../lib/language';
  import {onMount} from 'svelte';
  import type {WorldState,Ranking,HomeVisit,SocialState} from '../lib/multiplayer';
  import {CROPS,DISHES} from '../lib/world-state';
  import {newSave,ROOMS} from '../lib/model';
  import {imageUrl} from '../lib/assets';
  import FurnitureLayer from './FurnitureLayer.svelte';
  import Pou from './Pou.svelte';
  let {mode,social,world,ranking,home,onsend}:{mode:string;social:SocialState;world:WorldState|null;ranking:Ranking|null;home:HomeVisit|null;onsend:(p:Record<string,unknown>)=>void}=$props();
  let category=$state('food'),scope=$state('global'),target=$state(''),seed=$state('carrot'),room=$state('Bedroom'),clock=$state(Date.now()),offset=$state(0);
  const crops=Object.entries(CROPS);
  const visitor=$derived({...newSave(),appearance:{body:home?.home.body??'#d2a057',eyes:home?.home.eyes??'#111111',hat:'',glasses:'',outfit:''}});
  function loadRank(){onsend({type:'leaderboard',category,scope});}
  $effect(()=>{if(mode==='ranking')onsend({type:'leaderboard',category,scope});if(mode==='garden')onsend({type:'world_get',target:target||social.self.id});});
  $effect(()=>{if(world)offset=world.serverNow-Date.now();});
  onMount(()=>{const timer=setInterval(()=>clock=Date.now(),1000);return()=>clearInterval(timer);});
  function farm(type:string,plot:number){onsend({type,target:world?.owner.id??social.self.id,plot,crop:seed});}
</script>
{#if mode==='garden'}
  <h3>{translate($language,"Kebun bersama","Shared garden")}</h3><p>{translate($language,"Bibit gratis. Ajak teman menyiram untuk mempercepat tumbuh; pemilik dan perawat mendapat hasil panen.","Seeds are free. Ask friends to water for faster growth; owners and helpers share the harvest.")}</p>
  <label class="field">{translate($language,"Kebun","Garden")}<select bind:value={target}><option value="">{translate($language,"Kebunku","My garden")}</option>{#each social.friends as f}<option value={f.id}>{translate($language,"Kebun","Garden")} {f.name}</option>{/each}</select></label>
  <label class="field">{translate($language,"Bibit","Seed")}<select bind:value={seed}>{#each crops as [key,crop]}<option value={key}>{itemName($language,crop.name)} · {crop.growMs/60000} {translate($language,"menit","minutes")}</option>{/each}</select></label>
  {#if world}<p class="owner">{translate($language,"Kebun","Garden")} {world.owner.name}</p><div class="garden-plots">{#each world.garden as plot,index}{@const crop=crops.find(([key])=>key===plot.crop)?.[1]}{@const seconds=Math.max(0,Math.ceil((plot.readyAt-clock-offset)/1000))}<article>{#if crop}<img src={imageUrl(`food/${crop.food}.png`)} alt=""/><strong>{itemName($language,crop.name)}</strong><small>{seconds?translate($language,`${seconds}s lagi`,`${seconds}s remaining`):translate($language,'Siap panen','Ready to harvest')} · {plot.contributors.length} {translate($language,"perawat","helpers")}</small><button disabled={plot.contributors.includes(social.self.id)} onclick={()=>farm('garden_water',index)}>{translate($language,"Siram bersama","Water together")}</button><button disabled={seconds>0} onclick={()=>farm('garden_harvest',index)}>{translate($language,"Panen","Harvest")}</button>{:else}<img src={imageUrl('decor/plant.svg')} alt=""/><strong>{translate($language,"Petak","Plot")} {index+1}</strong><button onclick={()=>farm('garden_plant',index)}>{translate($language,"Tanam","Plant")}</button>{/if}</article>{/each}</div>
  <h4>{translate($language,"Dapur panen","Harvest kitchen")}</h4><p>{crops.map(([key,crop])=>`${itemName($language,crop.name)}: ${world.wallet[key]??0}`).join(' · ')}</p><div class="recipes">{#each DISHES as recipe}<button onclick={()=>onsend({type:'garden_cook',recipe:recipe.id})} disabled={Object.entries(recipe.cost).some(([key,n])=>(world.wallet[key]??0)<n)}><img src={imageUrl(`food/${recipe.food}.png`)} alt=""/><span>{itemName($language,recipe.name)} ×{recipe.amount}<small>{Object.entries(recipe.cost).filter(([,n])=>n).map(([key,n])=>`${n} ${itemName($language,CROPS[key as keyof typeof CROPS].name)}`).join(' + ')}</small></span></button>{/each}</div>{:else}<p>{translate($language,"Mengambil kebun dari server…","Loading garden from server…")}</p>{/if}
{:else if mode==='ranking'}
  <h3>{translate($language,'Peringkat','Leaderboard')}</h3><p>{translate($language,"Hasil dihitung server. Pilih kategori dan bandingkan dengan teman atau seluruh pemain di server ini.","Results are calculated by the server. Compare with friends or everyone on this server.")}</p><div class="ranking-controls"><select aria-label={translate($language,'Kategori peringkat','Leaderboard category')} bind:value={category}><option value="food">Food Drop Online</option><option value="adventure">{translate($language,"Petualangan co-op","Co-op adventure")}</option><option value="harvest">{translate($language,"Panen bersama","Shared harvest")}</option></select><select aria-label={translate($language,'Lingkup peringkat','Leaderboard scope')} bind:value={scope}><option value="global">Global</option><option value="friends">{translate($language,"Teman","Friends")}</option></select></div><button onclick={loadRank}>{translate($language,"Perbarui","Refresh")}</button>
  {#if ranking&&ranking.category===category&&ranking.scope===scope}<table><thead><tr><th>#</th><th>{translate($language,"Pemain","Player")}</th><th>{category==='harvest'?translate($language,'Panen','Harvest'):translate($language,'Skor','Score')}</th></tr></thead><tbody>{#each ranking.rows as row}<tr class:self={row.id===social.self.id}><td>{row.rank}</td><td>{row.name}{row.id===social.self.id?translate($language,' (kamu)',' (you)'):''}</td><td>{row.value}</td></tr>{/each}</tbody></table>{#if !ranking.rows.length}<p>{translate($language,"Belum ada hasil. Main atau panen untuk masuk peringkat.","No results yet. Play or harvest to join the leaderboard.")}</p>{/if}{#if ranking.self}<p>{translate($language,"Peringkatmu: #","Your rank: #")}{ranking.self.rank} · {ranking.self.value}</p>{/if}{:else}<p>{translate($language,"Memuat peringkat…","Loading leaderboard…")}</p>{/if}
{:else if mode==='home'}
  <h3>{translate($language,"Kunjungan rumah","Home visit")}</h3>{#if home}<p>{translate($language,"Rumah","Home")} {home.owner.name}</p><select aria-label={translate($language,'Ruangan yang dikunjungi','Visited room')} bind:value={room}>{#each ROOMS as r}<option value={r}>{roomName($language,r)}</option>{/each}</select><div class="home-visit"><FurnitureLayer placements={home.home.home.placements} {room}/><div class="visitor-pou"><Pou save={visitor} onpet={()=>false}/></div></div><div class="reactions">{#each [{id:'heart',label:'Suka'},{id:'wow',label:'Keren'},{id:'cozy',label:'Nyaman'}] as reaction}<button disabled={home.owner.id===social.self.id} onclick={()=>onsend({type:'home_react',target:home.owner.id,reaction:reaction.id})}>{itemName($language,reaction.label)} · {home.reactions[reaction.id]??0}</button>{/each}</div>{:else}<p>{translate($language,"Pilih Kunjungi pada daftar teman untuk melihat rumahnya.","Choose Visit from your friends list to see their home.")}</p>{/if}
{/if}
<style>
  h3{font-size:26px;font-weight:400;margin:12px 0}h4{font-size:23px;font-weight:400;margin:20px 0 10px}p{font:14px/1.5 system-ui,sans-serif;margin:9px 0}.field{display:block;text-align:left;font:13px/1.4 system-ui,sans-serif;margin:12px 0}select{width:100%;min-width:0;font:14px/1.4 system-ui,sans-serif;padding:9px;border:1.5px solid #b4a778;border-radius:8px;background:#fff8dc}.field select{display:block;margin-top:6px}button{border:1.5px solid #6f7b4e;border-radius:8px;padding:9px 11px;min-height:40px;background:#d5e9b7;color:#35402d;font:600 13px/1.3 system-ui,sans-serif}button:disabled{opacity:.45}.garden-plots{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.garden-plots article{display:flex;flex-direction:column;align-items:center;gap:7px;background:#fff5d9;border:2px solid #b9ac7d;border-radius:12px;padding:10px}.garden-plots img{width:60px;height:60px;object-fit:contain}.garden-plots strong{font-size:20px;font-weight:400}.garden-plots small{font:11px/1.4 system-ui,sans-serif}.garden-plots button{width:100%}.recipes{display:grid;gap:8px}.recipes button{display:flex;align-items:center;gap:10px;text-align:left;background:#fff6d8}.recipes img{width:45px;height:45px;object-fit:contain}.recipes span{font-size:17px}.recipes small{display:block;font:11px/1.4 system-ui,sans-serif;margin-top:3px}.ranking-controls{display:flex;gap:8px;margin:14px 0}table{width:100%;border-collapse:collapse;margin-top:16px;text-align:left;font:14px/1.4 system-ui,sans-serif}th,td{padding:10px 5px;border-bottom:1px solid #c3b68c}.self{background:#d5e8b4}td:last-child,th:last-child{text-align:right}.home-visit{position:relative;height:280px;background:linear-gradient(#c2dfe3 65%,#dfd0a6 65%);border:2px solid #8c9b77;border-radius:14px;overflow:hidden;margin:14px 0}.visitor-pou{position:absolute;inset:24% 25% 6%;z-index:2}.reactions{display:flex;gap:7px;justify-content:center;flex-wrap:wrap}
</style>
